import org.cups4j.CupsPrinter
import org.cups4j.CupsClient
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.Future
import java.util.concurrent.TimeUnit
import java.util.concurrent.TimeoutException

List<CupsPrinter> printerList = null;

try{
    ExecutorService executor = Executors.newSingleThreadExecutor();
    Future<List<CupsPrinter>> future = executor.submit(() -> {
        CupsClient cupsClient = new CupsClient(networkPrinter.serverHost, (int) networkPrinter.serverPort);
        printerList = cupsClient.getPrinters(); // Fetch printers
    })as Future<List<CupsPrinter>>;

    try {
        // Set timeout for getting printers
        future.get(3, TimeUnit.SECONDS);
    } catch (TimeoutException te) {
        System.err.println("⏳ Timeout: Unable to retrieve printers within " + 3 + " seconds.");
    } catch (Exception e) {
        System.err.println("❌ Error retrieving printers: " + e.getMessage());
    } finally {
        executor.shutdownNow(); // Ensure the executor is stopped
    }

    if (networkPrinter.printerName) {
        for (CupsPrinter curPrinter in printerList) {
            if (curPrinter.getName() == networkPrinter.printerName) {
                printerIpAddress = curPrinter.getLocation();
                break
            }
        }
    }
}catch(Exception e){
    e.printStackTrace()
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.concurrent.*;

String serverIp = networkPrinter.serverHost; // Replace with the remote server IP
String printerName = networkPrinter.printerName;

// Build the Expect command
String expectScript = String.format(
    "expect -c \""
    + "spawn ssh %s@%s \\\"lpstat -p %s\\\"; "
    + "expect \\\"password:\\\"; "
    + "send \\\"%s\\r\\\"; "
    + "expect eof"
    + "\"",
    username, serverIp, printerName, password
);

try {
    // Execute the Expect script
    ProcessBuilder processBuilder = new ProcessBuilder("bash", "-c", expectScript);
    processBuilder.redirectErrorStream(true);
    Process process = processBuilder.start();

    // Handle Output & Error Streams in Parallel
    ExecutorService executor = Executors.newFixedThreadPool(2);
    Future<String> outputFuture = executor.submit(() -> {
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        String result = "Unknown";
        while ((line = reader.readLine()) != null) {
            if (line.contains("printer")) {
                result = line.split(" ")[3];
                break;
            }
        }
        reader.close();
        printerStatus = result;
        return result;
    });

    // Timeout Handling
    try {
        outputFuture.get(3, TimeUnit.SECONDS);
    } catch (TimeoutException te) {
        System.err.println("⏳ Timeout: Process took too long!");
        process.destroyForcibly();  // Kill process if it is still running
    } catch (Exception e) {
        System.err.println("❌ Error retrieving printer status: " + e.getMessage());
    } finally {
        executor.shutdownNow(); // Ensure no thread keeps running
    }

} catch (IOException e) {
    System.err.println("❌ Error starting Expect script: " + e.getMessage());
}
